export function getTemplateSlug(country: string, religion: string, region: string): string {
  const countryMap: Record<string, string> = {
    // South Asia
    india: "indian",
    pakistan: "pakistani",
    bangladesh: "bangladeshi",
    sri_lanka: "sri_lankan",
    nepal: "nepali",
    maldives: "maldivian",
    afghanistan: "afghan",
    bhutan: "bhutanese",
    // Middle East
    saudi_arabia: "saudi",
    uae: "emirati",
    omani: "omani",
    yemeni: "yemeni",
    bahraini: "bahraini",
    qatari: "qatari",
    kuwaiti: "kuwaiti",
    iraqi: "iraqi",
    jordanian: "jordanian",
    lebanese: "lebanese",
    syrian: "syrian",
    palestinian: "palestinian",
    israeli: "israeli",
    iranian: "iranian",
    turkish: "turkish",
    egyptian: "egyptian",
    libyan: "libyan",
    tunisian: "tunisian",
    algerian: "algerian",
    moroccan: "moroccan",
    sudanese: "sudanese",
    mauritanian: "mauritanian",
    // East/SE Asia
    chinese: "chinese",
    japanese: "japanese",
    south_korean: "south_korean",
    mongolian: "mongolian",
    taiwanese: "taiwanese",
    filipino: "filipino",
    vietnamese: "vietnamese",
    thai: "thai",
    myanmar: "myanmar",
    cambodian: "cambodian",
    laotian: "laotian",
    malaysian: "malaysian",
    singaporean: "singaporean",
    indonesian: "indonesian",
    bruneian: "bruneian",
    // Central Asia
    kazakh: "kazakh",
    uzbek: "uzbek",
    turkmen: "turkmen",
    kyrgyz: "kyrgyz",
    tajik: "tajik",
    // Western
    american: "american",
    british: "british",
    canadian: "canadian",
    australian: "australian",
    new_zealander: "new_zealander",
    irish: "irish",
    french: "french",
    german: "german",
    italian: "italian",
    spanish: "spanish",
    portuguese: "portuguese",
    dutch: "dutch",
    belgian: "belgian",
    swiss: "swiss",
    austrian: "austrian",
    swedish: "swedish",
    norwegian: "norwegian",
    danish: "danish",
    finnish: "finnish",
    icelandic: "icelandic",
    polish: "polish",
    czech: "czech",
    slovak: "slovak",
    hungarian: "hungarian",
    romanian: "romanian",
    bulgarian: "bulgarian",
    greek: "greek",
    croatian: "croatian",
    slovenian: "slovenian",
    serbian: "serbian",
    bosnian: "bosnian",
    montenegrin: "montenegrin",
    macedonian: "macedonian",
    albanian: "albanian",
    ukrainian: "ukrainian",
    belarusian: "belarusian",
    russian: "russian",
    estonian: "estonian",
    latvian: "latvian",
    lithuanian: "lithuanian",
  };
  return `${religion}-${countryMap[country] || country}-${region.toLowerCase().replace(/\s+/g, "-")}`;
}

export function findTemplate(country: string, religion: string, region: string): WeddingTemplateData | undefined {
  const slug = getTemplateSlug(country, religion, region);
  return WEDDING_TEMPLATES.find((t) => t.slug === slug);
}

export function getTemplatesForCountry(country: string): WeddingTemplateData[] {
  return WEDDING_TEMPLATES.filter((t) => t.country === country);
}

export function getTemplatesForReligion(country: string, religion: string): WeddingTemplateData[] {
  return WEDDING_TEMPLATES.filter((t) => t.country === country && t.religion === religion);
}
